<?php
namespace App\Filament\Resources\Registrations\Tables;
use App\Models\MailTemplate; use App\Support\TemplateMailer; use Filament\Actions\Action; use Filament\Actions\BulkAction; use Filament\Actions\BulkActionGroup; use Filament\Actions\DeleteBulkAction; use Filament\Actions\EditAction; use Filament\Forms\Components\Select; use Filament\Notifications\Notification; use Filament\Tables\Columns\IconColumn; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Collection;
class RegistrationsTable { public static function configure(Table $table): Table { return $table->columns([TextColumn::make('user.name')->searchable(), TextColumn::make('event.name'), TextColumn::make('package.name'), TextColumn::make('status')->badge(), TextColumn::make('payment_status')->badge(), TextColumn::make('total_amount_cents')->money('EUR', divideBy: 100)])->filters([])->recordActions([Action::make('sendOnboarding')->label('Send onboarding mail')->action(fn ($record) => TemplateMailer::sendByType($record, 'onboarding'))->successNotificationTitle('Onboarding mail queued'), Action::make('sendPaymentReminder')->label('Send payment reminder')->action(fn ($record) => TemplateMailer::sendByType($record, 'payment'))->successNotificationTitle('Payment reminder queued'), Action::make('sendPracticalInfo')->label('Send practical info')->action(fn ($record) => TemplateMailer::sendByType($record, 'general'))->successNotificationTitle('Practical info queued'), EditAction::make(),])->toolbarActions([BulkActionGroup::make([BulkAction::make('sendTemplate')->label('Send selected template')->schema([Select::make('mail_template_id')->label('Mail template')->options(MailTemplate::where('is_active', true)->pluck('name', 'id'))->required()])->action(function (Collection $records, array $data): void { $template = MailTemplate::findOrFail($data['mail_template_id']); $records->each(fn ($record) => TemplateMailer::send($record, $template)); Notification::make()->title('Template sent')->success()->send(); }), DeleteBulkAction::make(),])]); } }
